package com.papazone.cart; import jakarta.persistence.*; @Entity @Table(name="cart_items") public class CartItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long customerId; private Long menuItemId; private String name; private double unitPrice; private int quantity; public Long getId(){return id;} public Long getCustomerId(){return customerId;} public void setCustomerId(Long v){customerId=v;} public Long getMenuItemId(){return menuItemId;} public void setMenuItemId(Long v){menuItemId=v;} public String getName(){return name;} public void setName(String v){name=v;} public double getUnitPrice(){return unitPrice;} public void setUnitPrice(double v){unitPrice=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} }
